3function EntryCard({ id, title, date, content, author, onDelete, onEdit }) {
4  const [isEditing, setIsEditing] = useState(false);
5  const [draftTitle, setDraftTitle] = useState(title);
6  const [draftContent, setDraftContent] = useState(content);
7
8  function handleStartEdit() {
9    setIsEditing(true);
10    setDraftTitle(title);
11    setDraftContent(content);
12  }
13
14  function handleSave() {
15    onEdit(id, draftTitle, draftContent);
16    setIsEditing(false);
17  }
18
19  function handleCancel() {
20    setIsEditing(false);
21    setDraftTitle(title);
22    setDraftContent(content);
23  }
24
25  if (isEditing) {
26    return (
27      <div className="entry-item">
28        <div className="entry-date">{date}</div>
29        <input
30          type="text"
31          value={draftTitle}
32          onChange={(e) => setDraftTitle(e.target.value)}
33          className="input-field"
34        />
35
36        <textarea
37          value={draftContent}
38          onChange={(e) => setDraftContent(e.target.value)}
39          className="textarea-field"
40          rows={4}
41        />
42
43        <div className="btn-group">
44          <button type="button" className="btn btn-secondary" onClick={handleCancel}>
45            Cancel
46          </button>
47          <button type="button" className="btn btn-primary" onClick={handleSave}>
48            Save
49          </button>
50
51        </div>
52      </div>
53    );
54  }
55
56  return (
57
58    <div className="entry-item">
59      <div className="entry-item-content">
60        <div className="entry-date">{date}</div>
61        <h4 className="entry-title">{title}</h4>
62        <p className="entry-content">{content}</p>
63        <p className="entry-author">{author}</p>
64        <div className="entry-actions">
65          <button 
66            type="button"
67            className="btn-icon btn-edit"
68            onClick={handleStartEdit}
69          >
70            Edit
71          </button>
72          <button
73            type="button"
74            className="btn-icon btn-delete"
75            onClick={() => onDelete(id)}
76          >
77            Delete
78          </button>
79        </div>  
80      </div>
81    </div>
82  );
83}
84
85export default EntryCard;

